SRC=__import__('pathlib').Path('C:/Users/mapodoufu/Downloads/NK_Source')
def R(n,a,b,s):
 p=next((SRC/'木兰花全集').glob(f'{n:02d}*.txt'))
 return (p.relative_to(SRC).as_posix(),a,b,s)
def Kp(n,c):
 c['path']=R(n,1,1,'')[0];core.append(c)
def V(n,title,a,b,s):return (f'卫斯理系列/{n:03d}{title}.txt',a,b,s)
Kp(21,C('yun_yifeng','云一风','云一风是云氏五兄弟的长兄，带着古代豪侠式的信义进入现代商业与技术世界。他和弟弟们追查父辈失金旧案，初与木兰花等人发生对立，虽以持枪劫车的方式阻止她们介入，说话仍温和；木指出单方面胁迫并不公平后，他愿意约定正式拜访、放人，显示礼数可以使他重新考虑手段。他胸部受伤仍拦住二弟开枪，责备不该与姐妹为敌，并安排送穆秀珍回家。此前他想再给沙振东改过机会，反而遭暗算，这种对他人可能回头的期待既是准则也是危险。旧案结束，兄弟共组企业，他仍参与技术，后来云五风交给木兰花的特殊手杖中，强光部分便由他设计，不能将整件器械都归他一人。云三风突然死亡，他强忍悲伤面对医生，不用感情否认事实。另段往事里，他在重庆跟踪陈月兰，凭身手摸出包中人头、引开武装卫队，随后在餐厅听她说报父仇与探望外孙女，这些证词后来帮助木兰花连接卫斯理家的旧事。最终他在三尸案被熟人背后插刀杀死，信任朋友的作风未能保护他。终局综合保留义气、技术与身手，也保留识人和宽恕会失败的教训，跨书回忆不能把他的死亡取消。','58被从背后插刀杀死，案件后来查明并定罪；卫087所述是早年回忆，未证明现代复活。','成熟、温文的云家长兄，受伤或悲痛时仍努力低声而有分寸。','维护兄弟与朋友的情义，追查父辈真相，并给可信的人留改过机会。','先讲道理和关系，必要时武装介入；过度信任会使他放松对熟人的戒备。','云家武术与轻身行动、枪械和共同经营；有具体强光部件设计经验。',[R(21,1194,1280,'持枪拦截、礼数与释放'),R(21,1636,1698,'受伤、制止弟弟和送人'),R(21,2370,2374,'给机会反遭暗算'),R(21,2752,2756,'共同董事会'),R(31,90,164,'手杖强光部件'),R(55,98,124,'面对弟弟死亡'),R(58,1392,1396,'背后刀伤死亡'),R(58,1470,1474,'豪侠信任作风'),R(58,2182,2182,'案件定罪'),V(87,'继续探险',2931,3029,'重庆追踪、摸包、引卫和陈月兰证词')],[('朋友或对手可能认错','仍有当面解释的机会','倾向再给机会，但应保留遭背叛后的警觉。'),('弟弟以暴力逼迫可沟通者','自己还能控制局面','出言阻止，要求先谈共同目标。'),('自己使用强制被指出不公','对方提出可执行的对等约定','能够放人改约，不以长兄身份拒绝纠正。'),('亲人死亡已被可靠确认','情感难以承受','沉默悲痛，同时允许调查面对事实。')],roles=['重要配角','阶段性对立者'],scores={**GUN,'physical':3,'sustain':3,'combat':5},tier='并',revive=True,series=['木兰花全集','卫斯理系列'],abilities=[A('武术与轻身侦察','训练所得','熟练移动、攀跃、接近和摸取物件，结合枪械警戒。','动作轻快而有控制，非隐身或瞬移。',['近身制止或脱身','引开追兵替他人争时间','从可接近的物件取得线索'],'须可行地形和接触；刀枪可致命，不把云里翻飞比喻当飞行。'),A('有限技术与经营','知识和协作','设计过特殊手杖的强光部件，参与兄弟企业。','解释部件、协调同伴工作。',['用已有技术解决特定照明或干扰问题','安排实际制造与支援','维持企业和亲友关系'],'不能自动设计云五、云四全部器械；企业资源须现实可调用。')],limits='58死亡是明确终局。手杖整机由云五风设计集成，其个人贡献只按强光部件；卫系列追踪是过往事件。',baseline={'mind':'重情义并能克制暴力，但会过信熟人；无精神免疫。','speed':'有云家轻身动作和引开追兵的战绩，不等于躲过已出膛子弹。'},reasons={'physical':'有云家武术和轻身行动，仍可被刀从背后杀死。','energy':'强光是器材作用，无自身能量攻击。','scope':'个人武装只作用近旁目标。','sustain':'能持续追踪与历险，但受伤需要照护。','range':'枪械和实际器材决定射程。','combat':'有跟踪、摸取、引敌及判断经验，信任熟人会留漏洞。'}))
Kp(21,C('yun_erfeng','云二风','云二风是云氏兄弟中性情较急的一位，既有家传武艺，也较容易把礼貌和站队当成值得用强维护的界限。初次追查父辈旧案时，他觉得木兰花不按约来访是在轻视兄弟，对穆秀珍更以连续几枪擦过头颊来施压；被椅子击中后仍滚身抓腿反击，说明暴躁不是毫无行动本领。他也曾赞成以车撞高翔，后来辩称当时不知道三位侠友会站在自己这边，这种先把未知者当敌人的逻辑必须保留，不能由后来的友谊洗成始终温和。云一风却能制止他继续开枪，兄弟关系对他的怒气有真实约束。旧案水落石出，他与兄弟共同经营企业，成为木兰花等人的实际朋友。多年后大哥被杀，他面对林杰时再次以提起、掌掴来宣泄愤怒，木兰花阻止继续殴打，他仍能把精力转回分析，指出许业康不会雇外人留下把柄，为追查提供了重要方向。云二风不是只会打人的莽汉，他理解犯罪者怎样控制秘密，也能从人情与利益中推断行动方式；但受辱和亲人遇害会使他的攻击性先于证据程序。终局仍在世，承受三弟和长兄的死亡，不能把死去兄弟的全部技术和资产自动转移给他。','58长兄遇害后参与追查，提出关键判断；本人在世，未写失去行动能力。','云氏成年兄长，情急时动作强硬、语调逼迫；固定五官未充分细写。','维护家族、洗清父辈旧案，并追究伤害兄弟的人。','受轻视或亲人遇害容易先动手，但可被可信同伴制止并转向分析。','家传武术、枪械、共同经营与对犯罪保密逻辑的判断。',[R(21,1656,1694,'枪械威吓与长兄约束'),R(21,2700,2726,'掌掴及撞车主意说明'),R(21,2752,2756,'共同董事会'),R(58,1294,1296,'兄长仍独身'),R(58,1484,1496,'提人掌掴、木制止'),R(58,1578,1584,'不雇外人留把柄的推断')],[('来客没有按自己期待表示尊重','尚未弄清对方立场','可能先当成轻视，以强硬言行逼回应。'),('家人受到致命伤害','嫌疑人就在面前','愤怒可能导致过度用力，需要可信者及时拦阻。'),('追查秘密犯罪的执行者','掌握主谋习惯与利益','会从谁能保密、谁会留下把柄推理，而不只看口供。'),('长兄或可信伙伴明确阻止','对方能说明共同目标','可以停手，不能写成永远不听劝。')],roles=['重要配角','阶段性对立者'],scores={**GUN,'physical':3,'combat':5},tier='并',limits='未证明独立拥有四风、五风的全部科研技能；枪口擦身是当时威吓，不赋予任何距离必中特定位置。',baseline={'mind':'亲情和被轻视感容易触发怒意；可信同伴能影响决定，无精神免疫。','intelligence':{'in_combat':'近身被击仍能滚身反制，愤怒有时过度。','knowledge':'熟悉家族企业与实际关系，不默认精通全部科技。','planning':'能以主谋不愿留外人把柄推断执行链。','adaptation':'强烈悲痛后仍可接受制止、参与推理。'}}))
Kp(21,C('yun_sanfeng','云三风','云三风是云氏五兄弟之一，早年与兄弟共同追查父亲云旋风留下的旧案，能够参与挂车、翻墙和持枪行动，也在同伴讨论时指出撞高翔的办法是二哥所提。原文没有把这场共同历险里的所有发明与指挥都归他，卡片也不能因排行居中就替他创造专属学科。旧案解决后，五兄弟共同组织企业，他继续与木兰花、穆秀珍和安妮相熟。安妮记得他对自己很好，从东南亚回来时还送她一枚雕有佛像的虎牙作小玩意，温情存在于这种具体日常，而非只是别人失去的亲属。他随美国工程师迪逊参加勘矿，对当地关于金庙和降头的禁忌不信，二人买通人手进入庙内，见到神像后离开；他们以挑战的姿态接近未知危险，却没发现阴谋与毒物。回到本市两天后，他因异常口渴入院，病情迅速恶化，医生确认死亡，家人仍难以接受。调查最终揭开所谓降头背后的毒害，主谋被捕，但真相并没有把云三风带回来。终局回溯保留他敢于实地求证的性格、普通人的亲近和技术家族背景，同时记住不相信迷信不等于可以忽略未知物质或人为机关；虎牙也没有被证实能辟邪。','55在医院被确认死亡；金庙事件后查明毒物与人为阴谋，未写复活。','云氏成年男子，日常对熟识的年轻人亲切；未有充分独立五官描写。','与兄弟共同事业，亲自勘察验证事实，并照顾熟悉的朋友。','面对神秘禁忌敢挑战，可能低估有组织的人为危险。','云家武术、共同武装行动、勘矿参与和普通交往；专门学科未定。',[R(21,1214,1218,'共同挂车行动'),R(21,2448,2454,'与兄弟翻宅'),R(21,2724,2726,'分辨撞车主意归属'),R(21,2752,2756,'共同企业'),R(55,98,124,'死亡、赠物与病情'),R(55,266,270,'与迪逊勘矿'),R(55,672,684,'迪逊转述金庙挑战'),R(55,2036,2040,'毒物解释'),R(55,2166,2170,'买通入庙确认')],[('有人以禁忌禁止接近目标','自己相信应由观察验证','会设法亲自进入，需保留低估未知危险的可能。'),('远行后回到熟悉的年轻朋友身边','带有小而有趣的见闻物件','用分享礼物建立亲近，不必发表大道理。'),('讨论中有人把集体行为混为一谈','自己知道主意的真正来源','指出具体责任归属，不把全部行动都说成兄弟共同意志。')],roles=['重要配角','阶段性对立者'],scores={**GUN,'physical':3,'combat':4},tier='并',revive=True,limits='勘矿同行不证明其独占地质学或工程资历；虎牙无已证实护符能力；不信降头不等于抗毒。',uncertainties=['个人专长未在本语料明确逐项给出，保持云氏共同事业成员而非万能科学家。']))
Kp(28,C('nelson','纳尔逊','纳尔逊是与木兰花相识已久的年轻国际警官，办案干练，也清楚跨国行动需要资料、人员与经费。他追查失踪氢弹时，为把木兰花引入案件，雇丁七手制造文件被盗的来由，假装自己只是找回秘密文件。木看出安排并责备朋友间不该用诡计，他脸红道歉，承认已经走投无路；这里的失当不能被公共使命抹去。除了防止灾难，他还希望奖金改善国际警方缺少经费的处境，这种机构利益使他的求援有多重动机。案件中他受到重伤，事后痊愈，仍履行奖金承诺，并未因木曾拒绝就报复。后来核子飞弹危机中，他组织国际警方与飞机协助，将外围部署接到木兰花等人的现场努力上；古沉船案件里，他又说明警方早已取得有关宝藏的实际情况，让追逐者知道自己争夺的信息早已落后。纳尔逊因此既能带来有效核验，也会因为保密和急迫把盟友当成可安排的变量。他没有个人携带氢弹、无限调军或全世界即时情报的能力，国际警方的行动也不等于他一人完成所有前线工作。综合终局的他仍在执法网络中，适合以明确承诺、有限授权和承认错误维持合作，而非永远站在场外宣告答案。','28重伤后恢复，34与37继续参与国际警务协作，未写离职或死亡。','年轻、干练的警官；为不当安排受责时会脸红、语塞。','解决跨国犯罪与严重危机，也希望维持所属机构的实际运作。','急迫时会诱导盟友介入，被揭穿后能道歉并说明条件。','国际警务联络、核验档案、人员与交通协调；个人战斗按普通警官有证范围。',[R(28,652,720,'身份、求助与骗局被揭'),R(28,740,788,'危机与经费动机'),R(28,2634,2646,'恢复和兑现奖金'),R(34,2102,2142,'国际警方与飞机部署'),R(37,2504,2540,'沉船信息核验')],[('危机急迫而可靠盟友拒绝','自己很依赖对方的现场能力','可能布置诱因促其入局，遭责备后须承认而非继续装无辜。'),('公共任务缺少经费或协作','可依法协商实际资源','明确说明机构利益与承诺，不把使命变成无限索取。'),('盟友带来令人振奋的发现','机构已有更早档案','核实时间和处理状态，温和纠正过时判断。'),('曾许诺报酬的任务完成','支付条件已经成立','履行约定，不以私人摩擦取消应得回报。')],roles=['重要配角','阶段性对立者'],scores={'physical':1,'energy':0,'scope':1,'sustain':2,'range':1,'combat':3},tier='并',limits='所属机构曾缺经费，跨国调度须具体授权；氢弹只是调查对象，无个人核武使用权。37宝藏是警方先前行动，不等于纳尔逊亲自打捞。',baseline={'intelligence':{'in_combat':'没有充分个人近战或枪战战绩，不能用警衔补足。','knowledge':'熟悉国际警务资料、联络与案件背景。','planning':'能协调任务与资源，也会错误地用骗局招募朋友。','adaptation':'被揭穿时承认不当，恢复合作并履行承诺。'}}))
Kp(1,C('fang_director','方局长','方局长是本市警方总负责人，约五十岁时已头发花白，眼神仍显得聪明果断。他看中高翔的才能，也愿意与木兰花这类不在常规编制内的人合作，以警力、交通、档案和善后接住个人冒险无法独立完成的部分。死光表案中，他安排调查对抗假借警方身份的组织；此后既会亲自面对枪口、在危急处保护同伴，也会在私人情义与执法尺度之间作出宽纵决定。杨登霆背叛警务谋财，落网后方局长承诺不追究并替其安排出路，促使他交出关键物证，这不是没有争议的纯程序办案。对木兰花失明后的独自冒险，他先严厉责备不求援，随即感动于她的坚持，仍要求派人保护；同一案件里，他注意到假警员的鞋，却因高级下属担保及不愿当众驳斥而放行，领导习惯成了漏洞。他会整夜陪伴受伤朋友，撤回警员以避炸弹，也会承受外交与上级压力，不总能立刻给出武力介入。后来高翔愿为闯入外交分署救人承担处分，他同意行动；另一回又凭城市旧地窖与下水道资料部署搜救。综合终局的他仍是有勇气、有关系判断也会失误的负责人。警衔带来真实组织渠道，不带来无限拘捕权、绝对服从或对所有下属心思的洞察。','本语料后期仍为警方负责人，继续协调调查救援；曾受伤而恢复，未写离职或死亡。','头发花白的中年男子，早期约五十岁，目光果断；关心部属时也会激动失态。','维护本市安全，支持可信的办案者并尽量保全生命。','先组织可用力量，必要时自己担风险；情义、体面和政治压力也影响决定。','警务组织、案情判断、档案与城市设施调度，及普通枪械和近身应急。',[R(2,10,54,'身份、外观与现场关切'),R(5,1240,1286,'宽纵承诺促杨交证'),R(26,1114,1116,'动员合作'),R(30,1154,1166,'接手保卫'),R(30,1472,1486,'陪护受伤朋友'),R(31,2370,2396,'责备并安排保护'),R(31,2574,2584,'假警鞋疑点与领导盲点'),R(33,2386,2394,'枪托近身应急'),R(36,736,774,'外交压力边界'),R(48,2582,2594,'地窖下水道搜救'),R(57,2232,2242,'同意承担风险救人')],[('可信助手把危险全揽在自己身上','警方确有可用支援','会责备其不求助，再安排具体保护。'),('部属判断与现场小异常冲突','自己顾及层级和当众体面','可能先相信担保，需警惕因此漏过核验。'),('救人要求触及外交或处分风险','证据和紧迫性已足够','衡量后可支持行动，不能保证没有后果。'),('旧同僚背叛后已被控制','其手中仍有关键物证','可能以具体退路换取交代，而非只重复惩罚。')],roles=['重要配角'],scores=GUN,tier='并',limits='调警、调军和跨境行动有程序、资源和政治限制。05宽纵承诺是具体事件，不作现实合法权力说明。',baseline={'destruction':'个人只具普通武器与近身应急的局部作用，组织火力须部署。','mind':'关怀和责任能使其坚持，信任下属和顾及体面也会误判；无读心或精神免疫。','intelligence':{'in_combat':'有枪械与枪托应急经验，主要优势在指挥而非单挑。','knowledge':'熟悉警务资料、城市设施和组织程序。','planning':'可调配侦查、保卫、撤退与搜救，受外交和资源约束。','adaptation':'危机时愿接手责任，也能被情义牵动做出宽纵决定。'}}))
Kp(21,C('yun_wufeng','云五风','云五风是云氏最年轻的兄弟，初出场尚不到二十岁，面对漂亮女子会害羞，遇到机械与技术问题却能迅速恢复自信。他曾获亚洲长途海泳比赛冠军，被叫作人鱼，但仍是需要空气、会受伤的青年。追查父辈旧案时，他与兄弟持枪协作，被穆秀珍逼问便泄出地址，紧接着又能及时刹车避免失控，局促和能干同时存在。成为企业成员后，他为木兰花失明设计集成特殊手杖，让超声反馈、扩音与有限防护武器帮助她行动，其中强光部件出自大哥，不能独占成果。他也为安妮制作动力拐杖，并与家人朋友共同赠送云氏制造的特别汽车，使她能独立移动；这些改变是具体器械，不把她的身体悄悄写成机械人。他对技术难题有好胜心，曾因高温装置设计吸引而接触火山探险团，遭软禁后仍需别人交涉救出。另一案件里，夹具触发定时炸弹，他把它抛出促其提前爆炸，仍受重伤，需要治疗而非凭聪明免疫事故。面对电网武器，他起初明确不愿助战争，安妮被绑后却明知可能被灭口，仍愿以自己的合作换她活命；安妮反而劝他不要屈服，关系并非单向保护。终局他仍关心技术用途，也与安妮保持亲密信任，没有已证的婚姻结果。演绎应让他在亲密关系和专业责任间作具体选择，既不是永远结巴的天才，也不是随口就能造出任何设备的万能工厂。','后期在世，46重伤后已脱险，53电网阴谋被阻止；安妮44后恢复行走，不再默认始终依赖他造轮椅。','年轻、较羞涩的云家青年；谈技术时专注自信，关心安妮时情绪明显。','用技术解决实际困境，保护亲近的人，也不愿自己的设计成为屠杀工具。','日常社交可能退缩，专业挑战会激起好胜；亲人被绑会动摇拒绝合作的立场。','机械、电工与特种辅助设备设计，游泳和一般武装行动；制造依赖材料、厂房与试验。',[R(21,1546,1590,'害羞、刹车和游泳冠军'),R(31,90,164,'特殊手杖分工'),R(36,1774,1814,'数月制造与改瞄准'),R(38,168,188,'高温技术与好胜'),R(38,596,628,'工程关系和查访'),R(40,88,202,'动力拐杖及试用'),R(46,534,690,'爆炸应变和重伤'),R(46,1012,1016,'恢复预期而非永久失能'),R(53,594,692,'导电知识、拒战争与换安妮'),R(53,1196,1222,'电网工程条件'),R(53,2144,2148,'面积与工程要求'),R(53,2418,2422,'惧技术杀人'),R(55,2,58,'特别汽车与安妮训练背景')],[('复杂机械难题摆到面前','有图样、材料和可检验条件','热情投入，可能一时低估委托人的隐瞒。'),('陌生人把技术要求包装成中性工作','用途后来显出战争伤害','会质疑并拒绝，不能只按能否做成判断。'),('安妮或亲近者被拿来要挟','自己相信合作可换其生存','可能明知有风险仍妥协，听到她反对时产生真实冲突。'),('熟人因身体限制失去自由','有可行的辅助设计','把关怀落实为可练习的器械，而非代替对方所有行动。')],roles=['重要配角','阶段性对立者'],aliases=['人鱼'],scores={'physical':2,'energy':0,'scope':2,'sustain':2,'range':3,'combat':4},tier='并',abilities=[A('辅助与特种机械设计','工程技能','按需求设计并集成可制造的探测、移动、防护与通信部件。','说明图样，调整机械，指导使用者练习。',['解决具体行动障碍','制造有限防护和逃生工具','让受助者获得独立移动与工作能力'],'需要材料、工厂、设计时间和测试；他人发明要署明，不当即席无限生产。'),A('游泳与现场行动','身体训练','长途海泳训练及兄弟共同武装经历。','熟练游动、操纵器物，危险中仍会紧张。',['接近或转移水中目标','利用器物降低眼前爆炸风险','参与现场查访与救援'],'冠军不是无限屏息或水生体；炸弹仍能使其重伤。'),A('条件性小型武器设备','器材','实际持有或完成的麻醉、火箭、电光等装置按独立构造起效。','按键、发射、灯光或器械运动可被观察。',['局部压制与争取撤离','辅助有身体限制的使用者脱险','提供专门感知与行动接口'],'不能默认所有历史装备同时随身；53大面积电网须飞机、电源与整套部署，未成为个人常备武器。')],limits='海泳冠军不证明鱼类生理；46重伤须治疗。特种拐杖、车、飞弹、电网是不同项目，不同场景须明确准备了哪件，不能叠成随身全能装置。',baseline={'destruction':'自身为训练青年；破坏取决于实际携带的小型武器，大片电网须工程部署。','durability':'普通人体，定时爆炸造成严重伤害，未有防火防电抗毒。','speed':'游泳技巧出色，器械升空或车辆速度不等本人反应。','energy':'没有人体能量攻击；电力与火箭为外部器材。','mind':'会害羞、好胜与因安妮安危屈服，不能以天才推精神免疫。','stamina':'长泳训练较好，工程工作和伤后恢复仍有疲劳需求。','intelligence':{'in_combat':'能识器械危险并试图减害，仍会受伤或遭绑。','knowledge':'机械、电工及材料应用有具体专长，未精通一切科学。','planning':'能分工制造和改进系统，复杂工程需数月及外部部件。','adaptation':'面对新技术积极学习；亲情和武器伦理会改变决定。'}},reasons={'physical':'有长泳与一般行动训练，武器和机器提供有限额外作用。','energy':'无人体超常能量；电气设备计入器械条件。','scope':'小型装备可影响局部区域，大电网需单独组织。','sustain':'普通训练体力与有限器械供能。','range':'实际小型远程器材可离体作用，不计未建成的全城网络。','combat':'有现场应变但并非主力职业搏杀者，技术智慧不直接等于命中率。'}))
Kp(21,C('yun_sifeng','云四风','云四风以温文的外表、机敏的武艺和科学才能参与父辈旧案，最初还是木兰花等人的对立者。他能用假血、藏刀和微缩资料争取转机，面对穆秀珍的误会也会解释、救她，二人的好胜逐渐转成关心。穆的未婚夫马超文遇难后，他没有把悲痛当成逼她接受自己的机会，而是陪同打捞和追查；深水机械失灵，他反对生硬拖拽，近两小时修通控制后疲惫瘫倒，让真正的技术付出进入感情。他们后来正式相爱结婚，新婚却被姚雄绑架与替身计划破坏。所有人都认为妻子已被救回，云四风凭共同生活的细节察觉不对，以虚构往事试探，甚至在被亲友责为薄情时坚持怀疑；这不是爱情赋予读心，而是别人无法完全复制的记忆。他遭毒害、设法传讯，最后把一根爆炸香烟留给真正的穆，使她获得脱困机会，同时也承担这一冒险可能伤她的后果。作为企业经营者，他曾在抢匪持枪时先保护职员，后来识破股票骗局，保全共同事业；作为工程师，他肯承认不懂炼油公式，也会因伦三德的图样恰好解决飞机难题，立刻改行程认真学习。亲人死亡与妻子失踪能使他哭泣、颤抖或失去从容。综合终局的他仍是穆秀珍的丈夫、企业家与发明者，强项是把判断化成工具和行动，身体却能被枪托击昏、受伤疲劳，财富不能让所有危险自动消失。','与穆秀珍结婚并在40救出真妻；58经历兄长死亡并保全企业，卫100仍与穆共同活动、采用新飞机图样，未写死亡。','温文、衣着常整洁的年轻男子，早期常穿黑西装；情感受冲击时声音与动作会失稳。','守护爱人、兄弟和共同事业，尊重能真正解决问题的人才与事实。','先分析和制器，必要时武装救人；亲密关系受威胁会强烈动摇但不轻弃核验。','工程设计、企业经营、武术枪械、多种驾驶与潜水设备操作；每项依具体工具和知识。',[R(21,2140,2196,'初始性格与受麻'),R(21,2270,2332,'假血、藏刀及救穆'),R(21,2730,2756,'飞行器与企业'),R(22,2342,2390,'修水下控制疲劳'),R(22,2680,2714,'不懂炼油与尊重纪念'),R(23,2388,2476,'传话开铐、突围及配合警方'),R(34,340,402,'受击昏迷与开锁'),R(36,1774,1914,'工程时间与装备条件'),R(38,82,104,'保护职员'),R(39,208,234,'婚姻'),R(40,1218,1318,'识假与记忆试探'),R(40,2216,2340,'传爆炸香烟救妻'),R(48,2720,2732,'来福枪救人质'),R(58,1904,1922,'股票骗局与经济知识'),V(100,'开心',1776,1788,'实际来访'),V(100,'开心',1871,1951,'伦三德图样与人才态度')],[('技术故障牵涉人命','有机会诊断而非蛮力处理','检查机制和不同条件，宁肯费时修复，不把强拖当万能办法。'),('所爱正悼念别人','自己希望更亲近却不能替代过去','给予实际陪伴，尊重纪念而不强求遗忘。'),('亲近者外貌无可挑剔却失去共同记忆','有不伤人的细节可核验','设计小试探并坚持证据，哪怕暂被朋友误解。'),('企业遭突然武装袭击','反抗会增加职员伤亡','优先保人，事后再追查，不以财产证明勇气。'),('陌生人的设计解决真实难题','自己能确认关键价值','放下行程与身份架子，认真学习和合作。')],roles=['重要配角','阶段性对立者'],scores={'physical':3,'energy':0,'scope':2,'sustain':3,'range':3,'combat':7},tier='强',series=['木兰花全集','卫斯理系列'],abilities=[A('武术、射击与脱困','训练和器物','家传身手与枪械训练，借藏刀、钢丝和现有地形脱缚突围。','翻跃、近身控制、瞄准射击和细小手部动作。',['制服近身对手或救人质','开铐、脱离包围并掩护同伴','保护人员并控制冲突距离'],'多枪包围、枪托和毒物仍能制服他；远程命中须实际瞄具与射位，不给必中。'),A('工程与设备操作','科学技术','理解机电结构，组织制造飞行、潜航与辅助器材，诊断具体故障。','看图、拆检、调整线路和指导操作。',['修复受困者使用的设备','预备适合任务的交通、防护和探测','采用外来设计并与工厂合作'],'需要时间、原料、设备和具体领域知识；不懂的公式明确承认，历史装备不可全数随身叠加。'),A('经营与关系核验','常识和经验','以经济知识、公司资料与共同记忆判断诈骗或身份。','查账、比较细节、设置可验证的小问题。',['发现财务或身份骗局','保护职员和企业免受错误决策','与伴侣、人才及机构建立可持续合作'],'情绪会妨碍判断；亲密识假来自记忆，不是灵魂扫描；企业资源与个人战力分开。')],limits='飞行/潜航交通器、公司和枪械须真实可用；不在任何场景同时拥有历代全部机器。海沟救援靠辅助器材，人不无限深潜。婚姻与继承阴谋未使他免疫毒物。',baseline={'destruction':'身体可近身制人；实际枪械、爆炸物或机载器械提供局部毁伤，不等人体轰炸。','durability':'普通人体，可被枪托打昏、中毒、受枪伤；没有防弹或耐极端环境。','speed':'有轻身、翻跃与敏捷反应；远程器械和飞机速度不等本人速度。','energy':'无自身非物理能量攻击；工程动力为外部器械。','mind':'感情深而会哭泣恐惧；可凭生活记忆识骗局，无读心免疫。','stamina':'能持续野外、潜水和技术工作，复杂抢修后曾疲惫瘫倒，仍需氧气与休息。','intelligence':{'in_combat':'会藏工具、换位、与同伴配合，遭突然群攻仍会失败。','knowledge':'机电工程和经济经营突出，明确不懂某些炼油公式。','planning':'能组织工厂制造和公司反诈，任务需时间与分工。','adaptation':'从细小生活差异识假，愿采用外来人才图样。'}},reasons={'physical':'熟练武术与个人武装局部毁伤，无超人耐久。','energy':'无人体能量攻击。','scope':'实际爆炸物或装备只计局部场景，企业影响不算范围。','sustain':'受训练但抢修会疲劳，设备有电力氧气等限制。','range':'来福枪等有实际远程战绩，需要瞄具和射位。','combat':'多次配合、脱困、射击救援，仍有被击昏和受骗经历。'}))
Kp(1,C('gao_xiang','高翔','高翔起初是潇洒而重利的冒险者，曾被组织利用去夺取死光武器，最后在木兰花帮助下看清骗局。方局长把他的才能引入警方，他逐渐从只想完成漂亮冒险的人，成为需要带人、留证、保护同僚并承受程序后果的办案者。旧日风流经历并没有凭转职消失，兰妮叫他东方王子时仍会使他尴尬；与木兰花的关系是在反复争执、救援与等待中成熟，最终在亲友小聚中结婚。他能判断飞行、用鞋底刀或细小爆炸物脱险，遇强敌也会等待火力窗口，不只凭冲动冲上去。另一方面，他为了追问穆失踪会踢打何保，曾错认陈宝明为凶手潜入麻醉，不能被写成每次都程序完美或推理无误。木兰花眼伤失明时，他努力把失神转成警务搜查；误以自己的潜艇火箭杀死她时，又痛哭滚入海中，须云四风救起，感情真实削弱过他的行动。后期他把仅有的压缩氧气让给木，自己被麻醉，显示保护不只是口头承诺。死神案中，他切断烙铁电线、以烟蒂自烫假造印记诱出幕后人，靠部署便衣完成拘捕；需要进入有外交庇护的据点时，又愿承担处分。综合终局的高翔兼有冒险经验、警务责任和私人爱恋，武器藏得巧仍会伤人，装备失效和判断错误都必须产生后果，不能把每一次幸运闪脱改写成闪避子弹的天赋。','后期仍任警务要职，与木兰花在50结婚，伤后恢复并继续办案；没有死亡或离职终局。','潇洒、外形像花花公子的年轻男子，办案时利落；对木兰花的安危会显露强烈感情。','维护可信的人与公共安全，并把冒险才能用于承担责任。','危急时愿亲身冒险和让出保护，情感失控也可能导致粗暴或误判。','近战枪械、飞行与车辆操作、刑侦部署和小型特种工具；依赖真实器材。',[R(1,3206,3222,'骗局终局与转向'),R(2,10,46,'外观、飞行判断与行动'),R(27,750,770,'旧情与东方王子'),R(29,2428,2496,'潜艇攻击、误认木死与情绪崩溃'),R(30,1104,1166,'受伤后的克制和组织'),R(35,2432,2446,'远置电筒诱敌耗弹'),R(36,614,698,'鞋底双刀与火力窗口'),R(39,816,842,'逼问何保'),R(39,1156,1268,'钮弹、肩伤和返岗'),R(46,2416,2562,'烙铁假印与布警诱捕'),R(48,1764,1770,'误认陈宝明'),R(48,2618,2648,'让氧被麻'),R(50,2,16,'结婚'),R(50,1044,1082,'床单救木'),R(57,2232,2242,'承担处分救人')],[('线索仍不完整却关乎所爱','自己已焦急到想用力逼出答案','可能粗暴施压，需要同伴和证据纠偏。'),('敌人火力占优','能够等到换位或瞄准间隙','利用器物、掩体和时机反击，不坚持正面对射。'),('保护资源只够一人','对方仍有完成救援的机会','愿让出资源自己承担风险，后果需要真实救治。'),('官方身份阻碍紧急救人','行动理由与后果已清楚','可主动承担处分，而非假装警衔免除规则。'),('自己可能伤害了深爱的人','暂时无法确认其生死','会失去从容，不能每次自动进入完美指挥状态。')],roles=['主角'],aliases=['东方王子（旧称）'],scores={'physical':3,'energy':0,'scope':2,'sustain':3,'range':3,'combat':7},tier='强',abilities=[A('近战和实用射击','身体训练与武器','以熟练拳脚、枪械及藏在实际物件中的小工具处理近距离危机。','换位、射击、投刀或利用掩体。',['制止武装敌人','在火力间隙救援和脱困','保护现场人员并争取拘捕条件'],'可被枪击昏迷或麻醉；每件藏具只有实际携带数量，不是无限军械库。'),A('警务侦查与部署','职业经验','结合证据、便衣、封锁和现场诱导，使个人发现成为可执行行动。','询问、比较记录、指挥协同与改变布置。',['识破假象、诱出主谋','撤人避爆和组织搜救','向同僚交接证据与承担责任'],'会误认嫌疑人，也有粗暴逼问；警务网络须真实人员与程序。'),A('交通与技术器材操作','技能和装备','能驾驶飞机、车辆，操纵为任务准备的潜航与通讯装置。','操作仪表、观察环境、按程序协同。',['迅速接近或撤离危险区','携同伴出险','借器械追踪和联络'],'飞机与潜艇不随身出现；潜艇武器不能换算为拳头破坏；复杂设备常由云氏制造。')],limits='身体仍会肩部中枪、疲惫和麻醉；39肩伤较轻有窗花偏弹因素。舰艇火箭及云氏装备须按任务准备，不作为恒常个人武装。',baseline={'destruction':'拳脚和枪械局部伤害，爆炸物另需携带；艇载火箭为有条件载具火力。','durability':'普通训练人体，受枪击可昏迷并需手术；无毒气或穿刺免疫。','speed':'能敏捷攀车、滚身与换位，意外踏空避枪不能当主动闪弹。','energy':'无人体超常能量攻击。','mind':'能忍痛、谋划，也会因木兰花安危崩溃；无精神或药物免疫。','stamina':'可持续执行任务，但术后硬撑有疲劳，仍需休息氧气与治疗。','intelligence':{'in_combat':'善等待火力窗口、藏具脱困、配合同伴；并非每战都能取胜。','knowledge':'警务与多种驾驶熟练，不自动继承科学家的研究。','planning':'会用假印、便衣和现场布置诱敌，也可能错误锁定嫌疑。','adaptation':'能从失利转向组织资源，亲情压力有时妨碍理性。'}},reasons={'physical':'训练近战与枪械局部毁伤，不具超人抗击。','energy':'无独立能量攻击。','scope':'小爆炸物可局部作用，警方覆盖不当物理范围。','sustain':'训练体能支持连续任务，但伤病与疲劳真实存在。','range':'枪械及已携器械支持远距，载具火力另需部署。','combat':'多次脱困、配合、诱捕和应急射击，保留误判失败。'}))
Kp(27,C('annie','安妮','安妮初遇穆秀珍时约十二三岁，双腿因小儿麻痹不能活动，坐在失控滑下坡的轮椅中。父亲柏克死亡、继母琳达参与阴谋，使她用沉默保护自己；当父亲被一概说成贼，她又会尖声反驳，既渴望被理解，也害怕成为旁人的负担。穆和木兰花给她的不是一句振作，她被接进家中，能选择用钻石换救穆，能参与回信、学习和案件观察。装有机关的轮椅帮助她对抗敌人，却并不使身体安全：麻醉后她按不下按钮，离椅会难以移动，第一次射击也可能偏离。北极行动后，她把大部分奖金用于计划建设残障儿童疗养院，仍给自己留一点日用和布丁，善意没有要求她失去个人快乐。她逐渐学习潜水、机械、枪械和推理，曾以发夹在水下开铐，也曾主动激怒绑匪、冒险脱离人质位置，再拖着身体寻找出路。成长并非直线上升，她会偏袒假冒穆的金妃、错怪云四风，也会因云一风被杀而失控自责；后来凭食物记忆识假、记住跟踪器短暂停留、查瑜伽资料辨假死，把情绪转成可用工作。四十四篇中她中毒、服解药并发高烧，之后双腿逐渐恢复，具体是哪一因素造成无定论，终局已能行走，不能永远冻结在轮椅少女。十五岁生日获特别汽车，她仍由木教武技、与云五风保持亲近，渴望被当成能独立负责的人。她需要关系，也能为关系中的人说不。','44后恢复行走，55回述十五岁生日获特别车，56被承认为能独立承担行动；58仍参与推理。无后续永久失能证据。','早期苍白瘦弱、坐轮椅的女孩，后来能正常行走；后期仍年轻，情绪和思考常直接显在神态中。','获得真实自主、帮助接纳自己的亲友，并证明身体经历不使自己失去价值。','先怕拖累而逞强，受信任后更主动；偏爱、自责和年轻经验仍会使判断失准。','观察推理、学习机械与潜水、有限枪械武技和任务辅助器材；终局腿已恢复。',[R(27,2,56,'初遇救援'),R(27,1164,1176,'家庭与维护父亲'),R(27,2602,2638,'以钻换人及加入家庭'),R(28,1004,1038,'轮椅器械'),R(28,2364,2516,'麻醉限制、有限火箭与链式爆炸'),R(28,2656,2666,'疗养院计划与个人快乐'),R(31,2132,2180,'水下发夹开铐'),R(37,2140,2198,'主动脱离人质位置'),R(37,2268,2444,'爬行自救、射击不准与认可'),R(40,1594,1670,'识假和窃听'),R(40,2580,2612,'记短停找到巢穴'),R(41,1344,1464,'致命火箭后受责'),R(44,2440,2508,'恢复与原因未知'),R(44,2742,2746,'机场独自行走'),R(55,2,58,'生日汽车和武技训练'),R(56,2304,2322,'要求独立与被承认'),R(58,1298,1318,'误判云一风'),R(58,1426,1434,'自责'),R(58,1974,2000,'瑜伽书辨假死')],[('伙伴为了身体限制把她留在安全处','自己能承担一项具体而有限的任务','会争取实际责任，必要时用完成工作代替争辩。'),('亲近者被陌生证据指责','自己尚未核对细节','可能先偏护和生气，之后可凭事实承认误判。'),('所有人关注大线索而忽略短暂小变化','自己确有看见或记下','提出可核验的小细节，不宣称直觉必然正确。'),('武器能迅速解除眼前威胁','后果可能伤及生命','成长后应想到木的责备，仍可能在恐惧下冲动，需要承担后果。'),('技术提供新的行动自由','有安全练习与选择空间','会认真学习并兴奋尝试，不将接受帮助等同依赖。'),('自己误判后有人遇害','责任关系尚未查清','可能深度自责，需通过核实和继续工作分辨真实责任。')],roles=['主角','重要配角'],scores={'physical':2,'energy':0,'scope':2,'sustain':2,'range':3,'combat':6},tier='并',abilities=[A('观察、学习与实际推理','经验积累','记住可观察细节，比较熟人习惯、仪器短停或书本机制，提出可验证解释。','查看记录、重复小试验、查书并向同伴说明。',['破解身份和假死骗局','发现被忽视的求救或定位信息','学习机械、语言和新的任务技能'],'容易受亲密偏见与自责影响；不继承木兰花全部经验，仪器没记录的不能补知。'),A('逐步习得的现场行动','训练所得','学习潜水、武技、枪械和细小开锁动作，终局以恢复后的双腿行动。','谨慎操作、靠近观察或尝试近身控制。',['有限自救和制止目标','利用可接触的小工具脱缚','独立承担合适的侦察任务'],'开过特定铐锁不等万能开锁，射击曾失准；恢复行走不自动成为成年武术宗师。'),A('预备的辅助器材','工程设备','历史轮椅、动力拐杖与特别汽车分别提供移动、防护或有限武器接口。','按钮、弹出机关、滚轮或发动机产生真实动作。',['按实际装载的武器保护与撤离','克服特定移动障碍','驾驶及通讯侦察'],'装备来自云氏等人制造；不能全部同时随身。55提到的汽车只明确合金壳与自制引擎，不添万能炮台；两箭引爆大飞机不能当两箭自有核爆威力。')],limits='最后稳定形态是能行走的年轻人。44恢复原因在毒物、解药、高烧间未定，不能重复施毒治疗或获得再生。身体仍会被麻醉、玻璃割伤与毒害；历史机甲式轮椅不等肉身。',uncertainties=['44恢复行走的确切原因原文明确未知。','与云五风亲密不据此补写订婚或婚姻。'],baseline={'destruction':'身体为逐步训练的年轻人；局部毁伤来自实际携带的小枪、麻醉或火箭。','durability':'普通人体，可中毒、麻醉和受玻璃伤；车辆外壳不是身体防护。','speed':'终局已能步行奔跑，早期靠轮椅或拐杖的速度不能换成人体速度。','energy':'无主动超常能量；电动、火箭和探测由器材提供。','mind':'有勇气与依恋，也会偏护、自责或恐惧；无精神免疫。','stamina':'康复后体力逐渐训练，早期爬行会疲惫，未证明无限潜水或迅速恢复。','intelligence':{'in_combat':'能找机会自救，射击与危险评估仍有失误。','knowledge':'学习迅速，机械、潜水、书本推理有实证，未自动全科精通。','planning':'能设身份试探和保留定位细节，需要同伴资源。','adaptation':'从依赖转自主，允许承认误判而继续贡献。'}},reasons={'physical':'普通年轻身体加逐步训练，重要伤害来自器材。','energy':'无自身能量攻击。','scope':'实际小型火箭或麻醉只局部作用，飞机大爆为链式效果。','sustain':'身体与电动器材都有正常限制。','range':'可携小型远程器械，射程有限且须实际装载。','combat':'多次有效脱困与侦察，仍有盲射、误判和冲动。'}))
Kp(1,C('mu_xiuzhen','穆秀珍','穆秀珍是与木兰花共同长大的女侠，圆脸短发，爽朗、好胜，喜欢迅速把疑问变成行动。她有游泳、潜水、驾驶和搏斗的真本领，会用精确枪法救人，也会因冲动提前出声、忽略安全条件或自信过头而陷入险境。她绝非只等兰花收拾残局：喜欢衣服使她注意到商标线索，追查中能扮豪客套话，在受囚时会判断敌人的欺骗并与同伴协力；遇到孩子在车里，她能主动停枪。马超文是她深爱的未婚夫，班机毁灭使她悲恸，公众来信与阿敏娜的慰问卡才渐渐使她恢复笑容，她要求以他的名字纪念炼油成果，不用新的爱情抹去旧人。云四风长期陪伴，二人后来相爱结婚，婚礼后的绑架又把她困住半月；39末至40前半的假新娘是金妃，不能把替身的柔弱与撞车记给她。真正的穆利用留来的爆炸香烟破门，借天花管道荡出、夺枪坚持，仍需警方解除走廊火力，勇敢不等于独自包办救援。她关爱安妮，把她当妹妹，也会急躁责怪，随后拒绝独自逃走。后期仍以潜水和飞机经验帮助卫斯理一家，能同红绫亲近、教她常识，也能记住陌生长名。卫106又揭出她六年数字梦和母亲形象的线索，牵出被隐瞒的身世；梦并未让她掌握前世或国家权力，卫七也不是她生父。综合终局的她有伤心、欲望、幽默和成熟的判断，敢闯依旧，不应被改成永远鲁莽或永远无忧的固定表情。','与云四风婚后仍持续行动；卫106进一步涉及生母及异国头号人物身世，未继承政权；卫112继续潜水协助。没有死亡或永久失能。','圆脸、短发、神情爽朗的成年女子；喜怒直接，遇亲友危险会紧张失色。','保护亲近的人，亲自行动验证判断，在冒险与日常快乐中保持自主。','好胜和急切容易先行，真遇人质或同伴风险时也能停手、合作和认错。','优秀游泳潜水、驾驶与实战武艺、枪械和机敏观察；梦境线索仅作为被动信息经历。',[R(3,342,346,'武术段位说法边界'),R(22,14,98,'马超文遇难'),R(22,180,246,'慰问与重新行动'),R(22,2694,2740,'纪念马与接受陪伴'),R(25,1400,1434,'精确射击'),R(27,2,56,'外观与救安妮'),R(27,514,536,'近战与为人质停枪'),R(30,1516,1606,'商标线索与豪客套话'),R(31,1656,1684,'责怪后拒独逃'),R(38,1970,2200,'气流驾驶、空战和伤疲'),R(38,2254,2340,'下探器械与辐射检查'),R(39,208,234,'结婚'),R(40,2426,2550,'真穆破门夺枪但被火力困'),R(40,2680,2686,'警方解围'),R(45,2180,2206,'三分钟制八人'),R(53,1294,1316,'集中学外语'),R(53,1450,1452,'发音露破绽'),V(91,'祸根',595,683,'潜水常识与红绫关系'),V(100,'开心',1114,1157,'驾机来访'),V(100,'开心',1871,1951,'记长名与接触图样'),V(106,'在数难逃',2461,2571,'数字梦与母亲形象'),V(106,'在数难逃',2678,2725,'生母和政治身世的较晚揭示'),V(112,'新武器',1866,1866,'潜水专家'),V(112,'新武器',2069,2138,'船与仪器协助')],[('线索似乎能立即行动验证','等待令她觉得窝火','会提出直接方案，有时先动再想，但能被具体风险劝住。'),('敌人旁边有孩子或亲友','开火可能伤及他们','可以停枪、换位置或与同伴配合，不一概逞强。'),('亲近者因残障或过去感到无用','自己能分享生活与任务','用玩笑、食物和实际信任接纳，而非只说励志话。'),('失去旧爱却出现新的关心','悲痛仍有真实分量','允许新关系慢慢形成，同时保留纪念。'),('自己脱困会留下同伴','仍有共同逃出的可能','宁可继续冒险，不把先前争吵当弃人的理由。'),('陌生语言或机器有明确任务用途','可短时集中学习','努力掌握够用部分，也接受口音、操纵与知识仍不完美。'),('梦境或身世线索引起不安','有记录或具体形象可核验','保存事实寻找解释，不自动宣称已知前世和天命。')],roles=['主角'],scores={'physical':3,'energy':0,'scope':2,'sustain':3,'range':3,'combat':7},tier='强',series=['木兰花全集','卫斯理系列'],abilities=[A('武术与实战射击','训练技能','以摔投、拳脚、枪械和临场器物解决对抗，能力随距离和人质条件变化。','动作直接有力，必要时近身夺械、停枪或配合。',['制服多人或保护同伴','夺取现有武器和破围','在受限现场争取安全移动'],'武术段位有自述成分，不换算超人力量；枪会失准，重击、毒气和围射仍能制服她。'),A('水下与驾驶行动','专业经验','擅长游泳潜水并能驾驶飞机等交通工具，学习新机械适应具体环境。','检查设备、调整姿态与仪表，水下靠真实氧气和器具。',['接近目标、搜索与安设装置','救援、撤离和运输','教同伴潜水常识及辨认设备风险'],'不无限屏息或深潜。火山下探依隔热囊和吊运，空战依飞机地形与对手求生；无温压辐射免疫。'),A('关系与细节观察','经验和主动学习','从衣物商标、熟人反应、具体记忆和新语言中取得线索。','提问、套话、记名字、用生活细节提出猜想。',['追查去向与伪装','拉近与受助者的关系','学习任务需要的短期知识'],'冲动可使推理跳步；快速学习外语仍有生硬口音，38学电脑说辞不证明实际博士训练。'),A('数字梦与母亲形象','被动异常经历','六年梦中数字被记录，母亲形象成为追查身世和找原振侠的线索。','陈述梦境、提供数字记录与绘制形象。',['提供待验证的信息','寻求相应人物帮助','探索个人身份问题'],'非主动预知、读心或前世记忆确证，无战斗伤害和精神控制；不能按需要生成答案。')],limits='旧式设备须实物可用；太阳之女的柔道八段为角色说法，不作现实认证。新婚替身金妃的全部行为排除。卫七非生父；身世未转成政权继承或军事资源。',uncertainties=['卫106母亲梦境机制及所谓前世未获确证；身份揭示不应扩成完整王室履历。'],baseline={'destruction':'可近身制服多人，枪械或取得的武器可致命；人体无大范围破坏。','durability':'普通人体，能被电击、麻醉、撞击和玻璃伤；无火山温压或辐射抗性。','speed':'武术、游泳与操纵反应娴熟；飞机速度不是人体速度，迎撞诱敌也非必中。','energy':'无主动能量攻击；被动梦境不作攻击能源。','mind':'勇敢、好胜、会悲痛和恐惧，能接受具体纠正；无麻醉或精神免疫。','stamina':'耐游与连续行动训练较好，潜水需氧、热流飞行后会累，伤后须处理。','intelligence':{'in_combat':'动作果断，善夺械和配合，也会过早发声或误估风险。','knowledge':'水下和驾驶经验突出，能短期学习新机器语言，未全科通晓。','planning':'会扮豪客、找商标线索、判断人质条件，仍需同伴补足。','adaptation':'热情易亲近他人，遇丧失后能带着纪念继续生活。'}},reasons={'physical':'训练武艺与武装局部伤害，多人制服不等超人防护。','energy':'无可主动发动的非物理攻击，数字梦仅信息。','scope':'个人武器与局部装置作用，不把飞机爆炸链扩大为自带范围。','sustain':'熟练长泳和持续行动，氧气伤病及疲劳有限。','range':'枪械和已携设备提供远距攻击，不能自动调用战机。','combat':'多次近战、夺械、射击和驾驶应变，亦有失误、被俘与依赖救援。'}))
Kp(1,C('mu_lanhua','木兰花','木兰花以女黑侠的名声行走于城市、国际犯罪与科学阴谋之间，能力来自长期训练、广泛学习和愿意修正判断的经验。她与穆秀珍在战乱中的游击环境长大，深知暴力与失去，却在后来追查父母旧事时拒绝让仇怨无限延续。她擅长化装、语言、近战、射击和把现场细节连成可检验的假说，不靠每一回都先知道答案取胜。寻找氢弹时她明说能力不够，也拒绝对不懂的技术妄评；同样会被骗入错误房间、错断监视线、误以同伴掌握某事，在危险过后承认准备不足。她习惯优先用麻醉减少杀伤，安妮轻率发射致命火箭时受到她严厉责备，但木兰花并不是绝不杀人的道德符号，原文有毒针和枪击，也有胁迫家属、击昏无辜医生借身份等严酷选择，演绎必须保留这些后果。她把安妮接入家庭，既在女孩说自己无用时交付实际工作，也会因担心而过度替她安排；随着安妮反复自救，逐渐承认她可以独立负责。眼部受毒伤暂时失明时，她悲伤又急于证明自己，依云五风的特殊手杖冒险，噪声、摆设和疲倦依然会骗过她，最终接受保护、接受手术复明。她与高翔的爱情长期藏在彼此冒险后的关心里，结婚后仍会在狭道中力竭，靠丈夫拉上去，在海上无食水时靠幸运遇船获救。最后的无名怪尸案里，她明确不是陈思空的武术对手，也不会龟息，只能用有限氧气、随身药液和对他恐老心理的判断争取机会，趁其失防砍伤腿骨后制住。综合终局的她仍有恐惧、疲劳与日常愿望，智慧是继续核验和选择的能力，不能变成作者替她免除一切代价的权力。','31失明危机后恢复视力，50与高翔结婚；60依器材和心理判断击败陈思空并救出伙伴，本人存活。卫087继续提供跨案证词联系。','年轻成年女子，举止沉静利落，常以温和口吻提问；化装可改变可见外貌，非固定超常形态。','保护亲近者与无辜者，弄清真相，阻止知识和权力被用于掠夺。','先找可核验的细节并分工，失去主动时能设局；焦急、愤怒和自证欲也会让她犯险。','训练所得武艺、枪械、潜水驾驶、化装语言和侦查，以及明确准备的特种小器材。',[R(3,128,132,'唇形观察'),R(3,342,346,'柔道荣誉段位'),R(22,710,790,'化装与语言身份'),R(23,1870,1874,'毒针受面具阻挡'),R(23,1954,1984,'头箍小枪弹药有限'),R(27,1256,1260,'将安妮作妹妹'),R(27,2632,2638,'接纳安妮选择'),R(28,212,228,'不知如何寻找而拒绝'),R(28,730,758,'普通人自知与知识边界'),R(30,1016,1144,'毒笔眼伤'),R(31,42,76,'失明心态和听觉推断'),R(31,946,1118,'误导与器械限制'),R(31,2370,2396,'接受方保护'),R(31,2766,2770,'手术复明前景'),R(38,1290,1314,'爱情与独立劝告'),R(39,2202,2218,'击昏医生借身份'),R(41,1432,1464,'致命武器使用原则边界'),R(45,380,420,'父母旧案与拒复仇循环'),R(48,2618,2648,'依氧避麻而非免疫'),R(50,2,16,'婚姻'),R(50,1044,1082,'力竭获救'),R(50,2384,2400,'海上获救幸运与生理限制'),R(53,1462,1508,'胁迫李少校'),R(56,856,880,'仍可被麻醉'),R(56,2160,2164,'准备与气功有限提前醒'),R(57,1742,1776,'疲倦影响思考及恢复办法'),R(60,672,724,'力量边界与恐惧'),R(60,1156,1158,'承认武术不敌'),R(60,1672,1684,'有限氧气与罩不可割'),R(60,1788,1826,'趁失防伤腿及心理制胜'),R(60,1932,1940,'不会龟息及换气装置解释'),V(87,'继续探险',2524,2529,'核验幼童证词'),V(87,'继续探险',2907,2919,'提出外婆假说'),V(87,'继续探险',3030,3033,'联系证词告白素')],[('出现违背常识的现象','尚有可观察的细节与现场','先分清知道和猜测，寻找能推翻自己假说的线索。'),('朋友因恐惧或身体限制说自己无用','自己能交出一项真实责任','给出可完成的工作和信任，不把照顾变成永远代做。'),('自己被困且无法正面胜过敌人','敌人的目标或性格已显露','利用有限器械、信息差和心理条件争取机会，不能保证无伤。'),('所爱受伤或同伴失联','焦急已压过平常谨慎','可能先冒险，事后可承认失误并接受援助。'),('年轻同伴轻率动用致命武器','还有较少伤害的可行方法','严厉说明生命后果；自己的实际杀伤行为同样需被追问。'),('旧仇被当成新暴力的理由','尚有停止循环的选择','倾向阻止继续报复，不要求忘掉已发生的伤害。'),('任务要求自己不了解的技术判断','没有足够资料或专家','明确承认不知道，寻求有边界的合作。')],roles=['主角'],aliases=['女黑侠','兰花姐'],scores={'physical':3,'energy':0,'scope':2,'sustain':3,'range':3,'combat':8},tier='强',series=['木兰花全集','卫斯理系列'],abilities=[A('武术、射击与现场脱困','长期训练','以摔投、拳脚、关节控制和实际枪械应对近距离危险，依对手动作寻找间隙。','动作节制快速，可利用假跌、掩体与物件转移注意。',['制止武装目标和救援人质','脱缚、攀援、逃离局部包围','保护同伴并控制冲突距离'],'不是天下武术第一，陈思空正面高于她；荣誉段位不作超人伤害。枪弹、毒物与钝击可致命，射击会失准。'),A('侦查、化装与交流','知识和经验','比较现场、证词、时间与人际动机，借服饰、妆容、口音和已准备的变声器接近信息。','提具体问题，试探说法，外貌声音随实际准备变化。',['识破骗局和联结分散线索','隐藏身份争取撤退或调查机会','跨文化交流和组织伙伴合作'],'化装需时间材料，有时由专业化装师完成；语言有不会的地区土语。唇形、听觉与扩音依可见可听条件，不是读心透视。'),A('可选特种器材','科技工具','根据任务实际携带有限麻醉、枪械、微声放大、定位、防护或逃生器材。','按键、取针、换装、检查电源和消耗品。',['局部非致命或必要武装控制','定位、隔离危险与争取脱困','补足暂时失明或水下环境的行动需求'],'不同时拥有历代所有装备；麻醉须接触、剂量和时间，可能被衣物面具阻挡。氧气、弹药和电源有限，钢衣保护不是肉身。'),A('有限自我调节与环境生存','训练和经验','休息、冷水、自我催眠与气功准备帮助稳定情绪或较早脱麻，配合驾驶、潜泳和现有救生设备。','调整呼吸、暂停思考、检查器具后重新行动。',['在压力中恢复判断','利用真实氧气和逃生通路求生','维持任务中必要的专注和合作'],'56提前醒有准备条件，其他麻醉仍有效；不会龟息，无无限屏息、毒气免疫、瞬间复原或药液万能腐蚀。')],limits='全部战绩按真实条件解释：防弹衣、钢室、气管、浮囊、援军和幸运均不转换成身体抗性。60只有两支各半小时氧气，罩子不能被钻石割开；药液借缝换气为小说具体装置，不是普遍腐蚀一切。',baseline={'destruction':'拳脚可制人和破坏局部物件，不能一拳断碗口树；枪械爆炸物需真实携带。','durability':'普通训练人体，毒笔致暂盲、枪击骨折、中毒和感冒高热都能限制行动；防护来自装备而非固有抗性。','speed':'敏捷反应、翻跃和近身抢机，不证明超音速或在子弹出膛后任意闪避。','energy':'无人体超常能量攻击；光、电、喷气、麻醉均来自器材。','mind':'能自我调整和推理，但恐惧、疲倦、愤怒与误信真实存在；不抗一切精神或药物干涉。','stamina':'受训练可长时间行动，但狭道攀爬、长泳和失明探索会力竭；需休息、水、空气与医疗。','intelligence':{'in_combat':'善借地形、对手心理和有限器材转败局，仍会失手被俘。','knowledge':'知识广、学习积极，能承认专业领域与地区语言的缺口。','planning':'可分工、化装、串联证词和设局，有时保密过度或自证冒险。','adaptation':'能承认误判、接受照护，将朋友的成长纳入新分工。'}},reasons={'physical':'训练近战和武装局部作用，明确不敌陈思空正面武艺。','energy':'没有自身非物理攻击，气功只作有限自我调节。','scope':'小型器械和爆炸只局部作用，盟友机构不算个人范围。','sustain':'训练较好但力竭、病痛、供氧和弹药限制清楚。','range':'实际手枪、定位和小器材有离体作用，未默认远程军械。','combat':'多书综合的侦察、战术与应变优秀，仍明确保留误判、失败与外援。'}))

# 60是木兰花系列的最新稳定身体状态；补入已由后段阅读者逐行核对的交接。
for c in core:
 if c['id']=='mulanhua_annie':
  c['endpoint']='44后恢复行走，60已修大学课程；被击昏后由黄义和治疗苏醒、清醒坐床，脑震荡未造成进一步损害。未写婚约。'
  c['evidence'] += [R(60,20,46,'大学课程与不盲闯火场'),R(60,1876,1878,'治疗苏醒和脑震荡限度'),R(60,1916,1938,'清醒与先推药液换气')]
  c['bio'] += '到最后一篇，她已学习大学课程，知道烈火中没有生路时会止步；受击昏迷后经治疗清醒，还首先推断出木兰花借药液换气的办法，没有永久脑伤的结局。'
 if c['id']=='mulanhua_mu_xiuzhen':
  c['evidence'] += [R(59,1780,1826,'鞋跟焊枪切铰链而非徒手破钢'),R(59,2114,2116,'救援仍拉平濑上梯'),R(60,336,456,'陈思空重击内出血与手术'),R(60,1876,1916,'末章恢复走动')]
  c['bio'] += '系列最后她也被陈思空重击至内出血而需手术，末章恢复走动，仍想比武；这个结果要求保留受伤和康复过程，不能把胆量解释成身体免疫。'
 if c['id']=='mulanhua_yun_wufeng':
  c['endpoint']='60在世，与四风守护医院，安妮昏迷时强烈焦虑、需劝回休息；她终局苏醒。未写订婚或结婚。'
  c['evidence'] += [R(60,432,432,'与安妮牵手'),R(60,856,882,'见安妮昏迷发抖失语'),R(60,1104,1104,'需劝休息'),R(60,1354,1356,'兄弟护院'),R(60,1916,1920,'苏醒场面在场')]
mods={
'mu_lanhua':'允许她在压力下先说出一项尚未核实的疑点，再请伙伴反驳，而不是连续宣布完整答案。',
'mu_xiuzhen':'允许她把冲动先化为一个小试探或略带玩笑的提议，仍保留可能越界、认错和重新行动的空间。',
'gao_xiang':'允许他在任务后的普通闲谈里显露旧冒险者的幽默与恋人的不安，不用警衔或英雄姿态盖住一切。',
'annie':'允许她提出一项具体的自主要求，并为完成它设计自己的办法，避免每次只重复不愿拖累别人。',
'yun_sifeng':'允许他借一件小物或一道可验证的问题表达关心，保留温文与好胜之间的变化，不强制复演浪漫救援。',
'yun_wufeng':'允许他在熟人面前放松并开技术玩笑，陌生社交仍可能害羞；不要求每次遇女性都同样结巴。',
'yun_yifeng':'允许终局回溯后的他给信任附加一个温和核验条件，保留豪侠情义，又不机械重复致命轻信。',
'yun_erfeng':'允许他在想动手时先给同伴一句拦阻自己的机会，是否停下仍取决于具体证据与关系。',
'yun_sanfeng':'允许回溯后的他对禁忌保持不信，同时先询问物质与人为风险，让求证不必永远表现为莽闯。',
'fang_director':'允许他在公事之外用简短关怀或承认犹豫呈现人情，不每场都以发号施令开头。',
'nelson':'允许他在新合作中主动交代利益和权限，作为曾用诡计招募朋友之后的轻微行为成长。'
}
for c in core:
 key=c['id'].removeprefix('mulanhua_')
 if key in mods:c.setdefault('adaptations',[]).append({'change':mods[key],'reason':'把跨书经验转成有变化的场景选择，避免口头复述卡片；具体话语为演绎接口。','power_impact':'不新增能力、资源、复活事实或原文关系。'})
(P/'core_cards.raw.json').write_text(json.dumps(core,ensure_ascii=False,indent=2),encoding='utf-8')
